let 종료중 = false;

async function shutdown(sig) {
  if (종료중) return;                 // 두 번 눌러도 한 번만
  종료중 = true;
  console.log(`${sig} 받음 — 정리 시작`);

  server.close();                     // 1) 새 요청 그만 받기
  await 진행중요청끝나기(5000);        // 2) 하던 것 마무리 (상한 필수)
  await db.end();                     // 3) 연결 정리
  process.exit(0);
}

process.on('SIGTERM', () => shutdown('SIGTERM'));
process.on('SIGINT', () => shutdown('SIGINT'));
